from playwright.sync_api import sync_playwright
import os; os.makedirs('test-output', exist_ok=True)
import os; os.makedirs('test-output/out', exist_ok=True)
errs=[]
def store(pg, js): return pg.evaluate(f"(async()=>{{const s=await import('./js/state/store.js'); {js} }})()")
with sync_playwright() as p:
    b=p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
    pg=b.new_page(viewport={'width':1300,'height':900}); pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto('http://localhost:8765/index.html'); pg.evaluate('localStorage.clear(); sessionStorage.clear()'); pg.reload(); pg.wait_for_timeout(700)
    # 97 grouped notifications: three likes on the same post
    store(pg, """const n=await import('./js/state/notifications.js'); for (const who of ['m-maya','m-theo','m-iris']) n.notify({ recipientIds:['m-leo'], actorId: who, kind:'like', text: `${s.getMember(who).name} liked your post “Bike lane meeting”`, moduleId:'x-mod', itemId:'x-post' });""")
    pg.locator('.app-bar__bell').click(); pg.wait_for_timeout(200)
    print('97 first line:', pg.locator('.notifications-menu__item').first.inner_text().replace('\n',' ')[:90], '| mark all:', pg.get_by_role('button', name='Mark all as read').count())
    pg.keyboard.press('Escape')
    # 83 feed headlines
    pg.evaluate("location.hash='#feed'"); pg.wait_for_timeout(900)
    print('83 headlines:', pg.locator('.feed-item__headline').all_inner_texts()[:5])
    # 100 repeating task + 101 select several on the house to-do
    mid=store(pg,"return s.getSpace('juniper').modules.find(m=>m.type==='todo').id")
    pg.evaluate(f"location.hash='#module-{mid}'"); pg.wait_for_timeout(800)
    add=pg.locator('.todo-page__add'); add.get_by_label('New task', exact=True).fill('Take out recycling'); add.get_by_label('Repeats').select_option('weekly'); add.locator('input[type=date]').fill('2026-11-16'); add.get_by_role('button', name='Add', exact=True).click(); pg.wait_for_timeout(300)
    row=pg.locator('.todo-row', has_text='Take out recycling'); print('100 row:', row.inner_text().replace('\n',' | '))
    row.locator('.todo-item__check').click(); pg.wait_for_timeout(300)
    print('   after done:', pg.locator('.todo-row', has_text='Take out recycling').inner_text().replace('\n',' | '), '| toast:', pg.locator('.toast').last.inner_text().replace('\n',' '))
    pg.locator('.toast').last.get_by_role('button', name='Undo').click(); pg.wait_for_timeout(300)
    print('   undo:', store(pg, f"return JSON.stringify(s.getModule('{mid}').data.tasks.filter(t=>t.text==='Take out recycling').map(t=>[t.due,t.done,t.doneCount]))"))
    pg.get_by_role('button', name='Select', exact=True).click(); pg.wait_for_timeout(200)
    rows=pg.locator('.todo-row--picking'); rows.nth(0).click(); rows.nth(1).click(); pg.wait_for_timeout(200)
    print('101 bar:', pg.locator('.todo-bulk').inner_text().replace('\n',' | ')[:120])
    pg.locator('.todo-bulk input[type=date]').fill('2026-11-30'); pg.wait_for_timeout(300)
    print('   dated:', store(pg, f"return s.getModule('{mid}').data.tasks.filter(t=>t.due==='2026-11-30').length"), '| selecting off:', pg.locator('.todo-bulk').is_hidden())
    pg.screenshot(path='test-output/todo-bulk.png')
    # 102 QR
    pg.evaluate("location.hash='#settings-juniper--members'"); pg.wait_for_timeout(800)
    if pg.get_by_role('button', name='Invite link', exact=True).count(): pg.get_by_role('button', name='Invite link', exact=True).click(); pg.wait_for_timeout(300)
    pg.get_by_role('button', name='QR code').click(); pg.wait_for_timeout(300)
    print('102 qr:', pg.locator('.qr-dialog h2').inner_text(), '| svg paths:', pg.locator('.qr-dialog svg path').count())
    pg.locator('.qr-dialog__code').screenshot(path='test-output/qr.png')
    pg.keyboard.press('Escape'); pg.wait_for_timeout(200); print('   closed:', pg.locator('.qr-dialog').count()==0)
    # 105 shortcuts
    pg.evaluate("location.hash='#feed'"); pg.wait_for_timeout(500); pg.locator('body').click(position={'x':5,'y':300}); pg.keyboard.press('Shift+Slash'); pg.wait_for_timeout(200)
    print('105 shortcuts:', pg.locator('.shortcuts__group-title').all_inner_texts())
    pg.keyboard.press('Escape'); pg.wait_for_timeout(100)
    # 106 schedule + history
    pg.evaluate("location.hash='#module-tenants-bulletin'"); pg.wait_for_timeout(800)
    pg.locator('.articles__list--page .article-teaser:not(.is-draft) .article-teaser__link').first.click(); pg.wait_for_timeout(500)
    pg.get_by_role('button', name='Edit', exact=True).count() and None
    print('106 can edit (Leo not author):', pg.locator('.news-article__tools').count())
    store(pg, "const a=await import('./js/state/accounts.js'); a.signIn('m-priya')"); pg.evaluate("location.hash='#feed'"); pg.wait_for_timeout(300); pg.evaluate("location.hash='#module-tenants-bulletin'"); pg.wait_for_timeout(800)
    pg.locator('.articles__list--page .article-teaser:not(.is-draft) .article-teaser__link').first.click(); pg.wait_for_timeout(500)
    pg.locator('.news-article__tools').get_by_role('button', name='Edit').click(); pg.wait_for_timeout(300)
    pg.locator('.article-editor').get_by_label('Headline', exact=True).fill('Crestline wants 9% more. The numbers say otherwise'); pg.get_by_role('button', name='Update').click(); pg.wait_for_timeout(500)
    print('   history:', pg.locator('.article-history summary').inner_text())
    print('   hist count:', pg.locator('.article-history').count()); pg.locator('.article-history summary').last.click(); pg.wait_for_timeout(200); pg.locator('.article-history').last.get_by_role('button', name='Read').first.click(); pg.wait_for_timeout(300)
    print('   old version:', pg.locator('.article-history__version > h2').inner_text())
    pg.locator('.article-history').get_by_role('button', name='Put this back').first.click(); pg.wait_for_timeout(400)
    print('   restored:', pg.locator('.news-article__headline').inner_text(), '|', pg.locator('.article-history summary').inner_text())
    # schedule a new one
    pg.locator('.news-article__back').click(); pg.wait_for_timeout(200); pg.get_by_role('button', name='Write an article').click(); pg.wait_for_timeout(300)
    ed=pg.locator('.article-editor'); ed.get_by_label('Headline', exact=True).fill('Meeting with Crestline: what to expect')
    ed.locator('[contenteditable=true]').first.click(); pg.keyboard.type('Three asks, one hour, and a room full of tenants.'); pg.wait_for_timeout(600)
    pg.get_by_role('button', name='Schedule').click(); pg.wait_for_timeout(400)
    print('   scheduled:', pg.locator('.news-article .article-kicker').first.inner_text())
    store(pg, "const a=await import('./js/state/accounts.js'); a.signIn('m-leo')"); pg.evaluate("location.hash='#feed'"); pg.wait_for_timeout(300); pg.evaluate("location.hash='#module-tenants-bulletin'"); pg.wait_for_timeout(800)
    print('   Leo sees:', pg.locator('.articles__list--page .article-teaser__headline').all_inner_texts())
    # 88 edit menu, 90 bell
    pg.evaluate("location.hash='#event-aid-ev-1'"); pg.wait_for_timeout(800)
    print('90 bell:', pg.locator('.event-page__remind .choice-menu__button').inner_text())
    print('errors', errs); b.close()
